$ErrorActionPreference='Stop';$R=Split-Path $PSScriptRoot -Parent;if(Get-Command python -ErrorAction SilentlyContinue){python -m py_compile "$R/python/app.py"};if(Get-Command node -ErrorAction SilentlyContinue){node --check "$R/node/app.js"};if(Get-Command go -ErrorAction SilentlyContinue){go build -o "$R/go/network-api.exe" "$R/go/main.go"};if(Get-Command cargo -ErrorAction SilentlyContinue){cargo check --manifest-path "$R/rust/Cargo.toml"};if(Get-Command javac -ErrorAction SilentlyContinue){New-Item -ItemType Directory -Force "$R/java/out"|Out-Null;javac "$R/java/Main.java" -d "$R/java/out"};if(Get-Command dotnet -ErrorAction SilentlyContinue){dotnet build "$R/csharp/BizXtreme.NetworkApi.csproj"};if(Get-Command c++ -ErrorAction SilentlyContinue){c++ -std=c++17 "$R/cpp/main.cpp" -o "$R/cpp/network-api.exe"};if(Get-Command dart -ErrorAction SilentlyContinue){dart analyze "$R/dart/bin/main.dart"};if(Get-Command kotlinc -ErrorAction SilentlyContinue){kotlinc "$R/kotlin/Main.kt" -d "$R/kotlin/network-api.jar"};if(Get-Command swiftc -ErrorAction SilentlyContinue){swiftc "$R/swift/main.swift" -o "$R/swift/network-api.exe"};if(Get-Command php -ErrorAction SilentlyContinue){php -l "$R/php/main.php"};if(Get-Command ruby -ErrorAction SilentlyContinue){ruby -c "$R/ruby/main.rb"};Write-Host 'NetworkUnified build checks complete for available toolchains.'
